// v0 scaffold for: No multi-channel asset library (video, brochures, case studies)
// Generated by batch_00 audit gaps. Persists to lazy gap_features table when DB available.
// TODO: configure credentials
import { Router, Request, Response } from 'express';

const FEATURE_TITLE: string = "No multi-channel asset library (video, brochures, case studies)";

let authMw: any = null;
try {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const m = require('../middleware/auth');
  authMw = typeof m === 'function' ? m : (m.authenticateToken || m.default || null);
} catch (e) {
  authMw = null;
}

let db: any = null;
try {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  db = require('../db');
} catch (e) {
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    db = require('../config/database');
  } catch (_) {
    db = null;
  }
}

const router = Router();
if (authMw) router.use(authMw);

async function ensureTable() {
  if (!db) return;
  try {
    const sql = `CREATE TABLE IF NOT EXISTS gap_features (
      id SERIAL PRIMARY KEY,
      project TEXT,
      slug TEXT,
      input JSONB,
      output JSONB,
      created_at TIMESTAMP DEFAULT NOW()
    )`;
    if (typeof db.query === 'function') {
      await db.query(sql);
    }
  } catch (err) { /* best effort */ }
}

async function persist(input: any, output: any) {
  if (!db) return;
  try {
    await ensureTable();
    if (typeof db.query === 'function') {
      await db.query(
        'INSERT INTO gap_features(project, slug, input, output) VALUES ($1, $2, $3, $4)',
        ['ai-sales-outreach', 'multi-channel-asset-library-video', JSON.stringify(input), JSON.stringify(output)]
      );
    }
  } catch (err) { /* ignore */ }
}

async function callOpenRouter(prompt: string) {
  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey) {
    return { stub: true, note: 'OPENROUTER_API_KEY not set. v0 stub response.' };
  }
  try {
    const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: process.env.OPENROUTER_MODEL || 'anthropic/claude-3.5-sonnet',
        messages: [
          { role: 'system', content: `You are an assistant for the feature: ${FEATURE_TITLE}.` },
          { role: 'user', content: prompt },
        ],
      }),
    });
    if (!res.ok) return { error: `OpenRouter HTTP ${res.status}` };
    const json: any = await res.json();
    return { choices: json?.choices, model: json?.model };
  } catch (err: any) {
    return { error: err.message };
  }
}

router.get('/health', (_req: Request, res: Response) => {
  res.json({ feature: 'multi-channel-asset-library-video', status: 'ok', version: 'v0', kind: 'gap' });
});

router.post('/run', async (req: Request, res: Response) => {
  try {
    const input = req.body || {};
    const prompt = typeof input.input === 'string' ? input.input : JSON.stringify(input);
    const aiResult = await callOpenRouter(prompt);
    const output = {
      feature: 'multi-channel-asset-library-video',
      title: FEATURE_TITLE,
      receivedKeys: Object.keys(input),
      ai: aiResult,
    };
    persist(input, output).catch(() => {});
    res.json({ success: true, result: output });
  } catch (err: any) {
    console.error('[gap-multi-channel-asset-library-video] error', err);
    res.status(500).json({ success: false, error: err?.message });
  }
});

export default router;
